function firstElement(a) {
  return a[0];
}

let steps = 0;
function sumAll(a) {
  let total = 0;
  for (let i = 0; i < a.length; i++) {
    steps++;
    total += a[i];
  }
  return total;
}

const ten = Array.from({ length: 10 }, (_, i) => i + 1);
const hundred = Array.from({ length: 100 }, (_, i) => i + 1);

steps = 0; sumAll(ten);
console.log("n = 10   ->", steps, "steps");
steps = 0; sumAll(hundred);
console.log("n = 100  ->", steps, "steps");

console.log("firstElement costs one step either way:", firstElement(ten), firstElement(hundred));

