function countPairs(n) {
  let steps = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      steps++;
    }
  }
  return steps;
}

function countTriangle(n) {
  let steps = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      steps++;
    }
  }
  return steps;
}

console.log("full    ", countPairs(5), countPairs(10), countPairs(20));
console.log("triangle", countTriangle(5), countTriangle(10), countTriangle(20));
console.log("doubling n from 10 to 20 multiplied the work by", countPairs(20) / countPairs(10));

