function halvings(n) {
  let steps = 0;
  while (n > 1) {
    n = Math.floor(n / 2);
    steps++;
  }
  return steps;
}

for (const n of [1, 2, 8, 1000, 1000000]) {
  console.log("n =", n, "-> halvings:", halvings(n));
}

const trail = [];
let m = 40;
while (m > 1) {
  m = Math.floor(m / 2);
  trail.push(m);
}
console.log("40 halves down through", trail.join(" -> "));

function mixedSteps(n) {
  let steps = 0;
  for (let i = 0; i < n; i++) {
    steps++;
  }
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      steps++;
    }
  }
  return steps;
}

for (const n of [10, 100, 1000]) {
  const actual = mixedSteps(n);
  console.log("n =", n, "steps =", actual, "n^2 =", n * n, "ratio =", (actual / (n * n)).toFixed(4));
}

