function secondLargest(a) {
  let best = -Infinity;
  let second = -Infinity;
  for (let i = 0; i < a.length; i++) {
    if (a[i] > best) {
      second = best;
      best = a[i];
    } else if (a[i] > second) {
      second = a[i];
    }
  }
  return second;
}

