function middleThree(a) {
  const mid = Math.floor(a.length / 2);
  return [a[mid - 1], a[mid], a[mid + 1]];
}

function countDigits(n) {
  let digits = 0;
  while (n > 0) {
    n = Math.floor(n / 10);
    digits++;
  }
  return digits;
}

function report(a) {
  let total = 0;
  for (let i = 0; i < a.length; i++) {
    total += a[i];
  }

  let pairs = 0;
  for (let i = 0; i < a.length; i++) {
    for (let j = 0; j < a.length; j++) {
      if (a[i] + a[j] === 0) pairs++;
    }
  }

  return [total, pairs];
}

function steps(n) {
  let c = 0;
  for (let i = 1; i < n; i = i * 2) {
    c++;
  }
  return c;
}

console.log(steps(1));
console.log(steps(8));
console.log(steps(64));

